function M({registerIndicator:p,sourceValues:d,nulls:y}){p({id:"oa-hanma",name:"Hanning Moving Average (HANMA)",category:"Trends FIR",placement:"onchart",inputs:[{key:"period",type:"number",label:"Period",default:10,min:1,max:5e3,step:1},{key:"source",type:"source",label:"Source",default:"close"}],plots:[{key:"hanma",type:"line",title:"HANMA",style:{color:"#ffeb3b",lineWidth:2}}],calc(o,r){const N=Math.max(1,Math.floor(Number(r.period)||10)),c=d(o,r.source??"close"),s=new Array(o.length).fill(NaN);let a=[1],u=1;for(let t=0;t<o.length;t++){const n=Math.min(t+1,N);if(n!==u){a=new Array(n);for(let e=0;e<n;e++)a[e]=.5*(1-Math.cos(2*Math.PI*e/(n-1)));u=n}let m=0,i=0;for(let e=0;e<n;e++){const h=c[t-e];if(!Number.isFinite(h))continue;const l=a[e];Number.isFinite(l)&&(m+=h*l,i+=l)}const f=i!==0?m/i:NaN;s[t]=Number.isFinite(f)?f:c[t]}return{hanma:y(s)}}})}export{M as default};
